PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "schema_history" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "statement" TEXT NOT NULL, "applied_at" TEXT NOT NULL, "module" TEXT, "migration" TEXT);
CREATE TABLE IF NOT EXISTS "audit" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "at" TEXT, "actor" TEXT, "tool" TEXT, "outcome" TEXT, "entity_type" TEXT, "entity_id" TEXT, "request_key" TEXT, "error_code" TEXT, "request_id" TEXT, "reason" TEXT, "credential" TEXT);
CREATE TABLE IF NOT EXISTS "receipt" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "actor" TEXT, "tool" TEXT, "request_key" TEXT, "input_hash" TEXT, "redacted" INTEGER, "result" TEXT, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "confirmation" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "token_hash" TEXT, "actor" TEXT, "tool" TEXT, "input_hash" TEXT, "expires_at" TEXT, "request_id" TEXT, "used_at" TEXT, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "setting" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "key" TEXT, "value" TEXT);
CREATE TABLE IF NOT EXISTS "fake_accounting_calls" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "intent_id" TEXT, "invoice_id" TEXT, "external_ref" TEXT, "total_ore" INTEGER, "at" TEXT);
CREATE TABLE IF NOT EXISTS "jobs" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "kind" TEXT, "queue" TEXT, "arguments" TEXT, "state" TEXT DEFAULT 'queued', "priority" INTEGER DEFAULT 0, "due_at" TEXT, "attempts" INTEGER DEFAULT 0, "max_attempts" INTEGER, "snoozes" INTEGER DEFAULT 0, "unique_key" TEXT, "enqueued_at" TEXT, "enqueued_by" TEXT, "claimed_by" TEXT, "started_at" TEXT, "finished_at" TEXT, "last_error" TEXT, "errors" TEXT, "note" TEXT);
CREATE TABLE IF NOT EXISTS "job_schedules" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "name" TEXT, "first_seen_at" TEXT, "last_occurrence" TEXT, "last_occurrence_at" TEXT, "last_job_id" TEXT, "last_enqueued" INTEGER);
CREATE TABLE IF NOT EXISTS "job_processes" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "started_at" TEXT, "lock_key" INTEGER);
CREATE TABLE IF NOT EXISTS "mails" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "to" TEXT, "subject" TEXT, "text" TEXT, "html" TEXT, "reply_to" TEXT, "key" TEXT, "status" TEXT DEFAULT 'queued', "attempts" INTEGER DEFAULT 0, "job_id" TEXT, "last_error" TEXT, "provider" TEXT, "provider_id" TEXT, "created_at" TEXT, "sent_at" TEXT);
CREATE TABLE IF NOT EXISTS "attachments" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "entity" TEXT, "record_id" TEXT, "filename" TEXT, "content_type" TEXT, "size" INTEGER, "width" INTEGER, "height" INTEGER, "sha256" TEXT, "created_at" TEXT, "created_by" TEXT, "account" TEXT);
CREATE TABLE IF NOT EXISTS "workflows" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "key" TEXT, "request_id" TEXT, "kind" TEXT, "order_id" TEXT, "customer_id" TEXT, "due_at" TEXT, "status" TEXT DEFAULT 'planlagt', "executed_at" TEXT, "note" TEXT, "subject_id" TEXT);
CREATE TABLE IF NOT EXISTS "error_groups" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "fingerprint" TEXT, "code" TEXT, "error_type" TEXT, "message" TEXT, "tool" TEXT, "backtrace" TEXT, "request_id" TEXT, "first_seen_at" TEXT, "last_seen_at" TEXT, "count" INTEGER DEFAULT 0, "status" TEXT DEFAULT 'open', "status_changed_at" TEXT, "status_changed_by" TEXT, "notified_at" TEXT);
CREATE TABLE IF NOT EXISTS "error_occurrences" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "group_id" TEXT, "at" TEXT, "request_id" TEXT, "kind" TEXT, "tool" TEXT, "actor" TEXT, "message" TEXT, "total_ms" TEXT);
CREATE TABLE IF NOT EXISTS "accounts" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "name" TEXT, "display_name" TEXT, "kind" TEXT, "role" TEXT, "email" TEXT, "status" TEXT DEFAULT 'active', "created_at" TEXT, "created_by" TEXT, "invited_at" TEXT);
CREATE TABLE IF NOT EXISTS "access_tokens" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "account_id" TEXT, "label" TEXT, "role" TEXT, "prefix" TEXT, "token_hash" TEXT, "expires_at" TEXT, "created_at" TEXT, "created_by" TEXT, "last_used_at" TEXT, "revoked_at" TEXT);
CREATE TABLE IF NOT EXISTS "sessions" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "account_id" TEXT, "token_hash" TEXT, "created_at" TEXT, "last_seen_at" TEXT);
CREATE TABLE IF NOT EXISTS "account_identities" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "account_id" TEXT, "strategy" TEXT, "issuer" TEXT, "subject" TEXT, "email" TEXT, "linked_at" TEXT, "last_used_at" TEXT);
CREATE TABLE IF NOT EXISTS "sign_in_attempts" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "strategy" TEXT, "state_hash" TEXT, "nonce" TEXT, "verifier" TEXT, "purpose" TEXT, "setup_hash" TEXT, "account_name" TEXT, "display_name" TEXT, "expires_at" TEXT);
CREATE TABLE IF NOT EXISTS "push_subscriptions" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "account" TEXT, "endpoint" TEXT, "p256dh" TEXT, "auth" TEXT, "server_key" TEXT, "session" TEXT, "device" TEXT, "created_at" TEXT, "tested_at" TEXT);
CREATE TABLE IF NOT EXISTS "saved_queries" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "account" TEXT, "page" TEXT, "query" TEXT);
CREATE TABLE IF NOT EXISTS "customers" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "marketing_consent" INTEGER, "consent_source" TEXT, "consent_at" TEXT, "erased" INTEGER, "erased_at" TEXT, "revision" INTEGER DEFAULT 1, "name" TEXT, "email" TEXT, "phone" TEXT, "notes" TEXT, "completed_orders" INTEGER DEFAULT 0, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "products" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "revision" INTEGER DEFAULT 1, "name" TEXT, "kind" TEXT, "unit" TEXT, "unit_price_ore" INTEGER, "stock_tracked" INTEGER, "units_owned" INTEGER DEFAULT 0, "manual_url" TEXT, "created_at" TEXT, "article_id" TEXT, "department" TEXT, "department_revision" INTEGER DEFAULT 1, "requirements" TEXT, "lite_requirement_id" TEXT, "lite_recipe_id" TEXT);
CREATE TABLE IF NOT EXISTS "recipes" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "revision" INTEGER DEFAULT 1, "name" TEXT, "description" TEXT, "active" INTEGER DEFAULT 1, "lines" TEXT);
CREATE TABLE IF NOT EXISTS "choice_groups" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "revision" INTEGER DEFAULT 1, "name" TEXT, "active" INTEGER DEFAULT 1, "members" TEXT);
CREATE TABLE IF NOT EXISTS "catalog_changes" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "resource_type" TEXT, "resource_id" TEXT, "operation" TEXT, "changed_fields" TEXT, "at" TEXT, "by" TEXT, "product_id" TEXT);
CREATE TABLE IF NOT EXISTS "stock_levels" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "product_id" TEXT, "on_hand" INTEGER DEFAULT 0, "revision" INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS "articles" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "revision" INTEGER DEFAULT 1, "name" TEXT, "sku" TEXT, "unit" TEXT, "package_size" NUMERIC, "balance" NUMERIC DEFAULT 0, "movement_revision" INTEGER DEFAULT 0, "min_level" NUMERIC, "max_level" NUMERIC, "cost_price_ore" INTEGER, "supplier" TEXT, "lead_days" INTEGER DEFAULT 0, "department" TEXT, "department_revision" INTEGER DEFAULT 1, "active" INTEGER DEFAULT 1, "product_id" TEXT, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "inventory_movements" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "product_id" TEXT, "kind" TEXT, "quantity" NUMERIC, "revision" INTEGER, "balance_after" NUMERIC, "reason" TEXT, "order_id" TEXT, "at" TEXT, "article_id" TEXT, "balance_updated" INTEGER DEFAULT 1, "by" TEXT);
CREATE TABLE IF NOT EXISTS "reservations" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "product_id" TEXT, "quantity" NUMERIC, "needed_on" TEXT, "article_id" TEXT);
CREATE TABLE IF NOT EXISTS "transfers" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "target_type" TEXT, "target_id" TEXT, "from_department" TEXT, "to_department" TEXT, "note" TEXT, "by" TEXT, "at" TEXT);
CREATE TABLE IF NOT EXISTS "consumption_commands" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "order_revision" INTEGER, "effective_date" TEXT, "fingerprint" TEXT);
CREATE TABLE IF NOT EXISTS "reviews" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "kind" TEXT, "status" TEXT DEFAULT 'pending', "priority" TEXT DEFAULT 'normal', "subject" TEXT, "proposal" TEXT, "source" TEXT, "idempotency_key" TEXT, "title" TEXT, "summary" TEXT, "requested_by" TEXT, "requested_at" TEXT, "due_at" TEXT, "reviewed_by" TEXT, "reviewed_at" TEXT, "note" TEXT, "subject_id" TEXT, "proposal_id" TEXT);
CREATE TABLE IF NOT EXISTS "orders" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "source" TEXT, "open_questions" TEXT, "revision" INTEGER DEFAULT 1, "status" TEXT DEFAULT 'utkast', "customer_id" TEXT, "event_date" TEXT, "end_date" TEXT, "delivery_address" TEXT, "lines" TEXT, "tags" TEXT, "department" TEXT, "price_mode" TEXT DEFAULT 'automatisk', "discount_percent" NUMERIC, "discount_ore_input" INTEGER, "price_reason" TEXT, "logistics" TEXT, "catalog_total_ore" INTEGER DEFAULT 0, "subtotal_ore" INTEGER DEFAULT 0, "discount_ore" INTEGER DEFAULT 0, "adjustment_ore" INTEGER DEFAULT 0, "total_ore" INTEGER DEFAULT 0, "requirements" TEXT, "pickup" TEXT, "return" TEXT, "accepted_snapshot_stale" INTEGER, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "bookings" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "product_id" TEXT, "quantity" INTEGER, "from_date" TEXT, "to_date" TEXT);
CREATE TABLE IF NOT EXISTS "quotes" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "revision" INTEGER DEFAULT 1, "status" TEXT DEFAULT 'awaiting_response', "offered_at" TEXT, "expires_at" TEXT, "responded_at" TEXT, "snapshot" TEXT, "basis" TEXT, "access_code" TEXT);
CREATE TABLE IF NOT EXISTS "checklist_items" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "order_line_id" TEXT, "origin" TEXT DEFAULT 'manual', "source_key" TEXT, "description" TEXT, "category" TEXT, "computed_quantity" NUMERIC, "done_quantity" NUMERIC, "done" INTEGER);
CREATE TABLE IF NOT EXISTS "plans" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "revision" INTEGER, "status" TEXT, "fingerprint" TEXT, "activation" TEXT, "activated_at" TEXT, "activated_by" TEXT, "note" TEXT, "order_revision" INTEGER, "lines" TEXT);
CREATE TABLE IF NOT EXISTS "plan_impacts" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "catalog_change_id" TEXT, "order_id" TEXT, "status" TEXT, "detail" TEXT, "plan_revision" INTEGER);
CREATE TABLE IF NOT EXISTS "plan_impact_queue" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "catalog_change_id" TEXT, "order_id" TEXT, "attempts" INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS "employees" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "name" TEXT, "actor" TEXT, "role" TEXT, "department" TEXT, "auto_assign_in_department" INTEGER, "active" INTEGER DEFAULT 1, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "assignments" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "employee_id" TEXT, "auto" INTEGER, "auto_department" TEXT, "started_at" TEXT, "ended_at" TEXT);
CREATE TABLE IF NOT EXISTS "assignment_overrides" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "assignment_id" TEXT, "order_id" TEXT, "employee_id" TEXT, "reason" TEXT, "conflict_ids" TEXT, "conflict_summary" TEXT, "created_by" TEXT, "created_at" TEXT);
CREATE TABLE IF NOT EXISTS "unavailabilities" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "employee_id" TEXT, "start_date" TEXT, "end_date" TEXT, "whole_day" INTEGER DEFAULT 1, "start_time" TEXT, "end_time" TEXT, "private_note" TEXT, "version" INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS "work_sessions" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "order_id" TEXT, "assignment_id" TEXT, "employee_id" TEXT, "started_at" TEXT, "ended_at" TEXT, "duration_seconds" INTEGER, "note" TEXT, "source" TEXT DEFAULT 'live');
CREATE TABLE IF NOT EXISTS "notifications" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "type" TEXT, "recipient" TEXT, "text" TEXT, "link" TEXT, "subject_type" TEXT, "subject_id" TEXT, "order_id" TEXT, "event_id" TEXT, "created_at" TEXT, "read_at" TEXT);
CREATE TABLE IF NOT EXISTS "henvendelser" ("seq" INTEGER PRIMARY KEY AUTOINCREMENT, "id" TEXT NOT NULL UNIQUE, "kind" TEXT DEFAULT 'epost', "status" TEXT DEFAULT 'ny', "from_name" TEXT, "from_email" TEXT, "subject" TEXT, "body" TEXT, "received_at" TEXT, "message_ref" TEXT, "customer_id" TEXT, "order_id" TEXT, "match" TEXT DEFAULT 'ingen', "created_order_id" TEXT, "questions" TEXT, "marketing_consent" INTEGER, "handled_by" TEXT, "handled_at" TEXT, "note" TEXT, "request_id" TEXT);
PRAGMA writable_schema=ON;
CREATE TABLE IF NOT EXISTS sqlite_sequence(name,seq);
DELETE FROM sqlite_sequence;
CREATE INDEX "idx_audit_entity_type_entity_id" ON "audit" ("entity_type", "entity_id");
CREATE UNIQUE INDEX "uq_receipt_actor_tool_request_key" ON "receipt" ("actor", "tool", "request_key");
CREATE UNIQUE INDEX "uq_confirmation_token_hash" ON "confirmation" ("token_hash");
CREATE UNIQUE INDEX "uq_setting_key" ON "setting" ("key");
CREATE INDEX "idx_fake_accounting_calls_intent_id" ON "fake_accounting_calls" ("intent_id");
CREATE INDEX "idx_fake_accounting_calls_invoice_id" ON "fake_accounting_calls" ("invoice_id");
CREATE INDEX "idx_jobs_state_queue_due_at" ON "jobs" ("state", "queue", "due_at");
CREATE INDEX "idx_jobs_kind_unique_key" ON "jobs" ("kind", "unique_key");
CREATE INDEX "idx_jobs_claimed_by" ON "jobs" ("claimed_by");
