CREATE INDEX "idx_workflows_status_due_at" ON "workflows" ("status", "due_at");
CREATE INDEX "idx_workflows_kind_key_status" ON "workflows" ("kind", "key", "status");
CREATE INDEX "idx_error_groups_status_last_seen_at" ON "error_groups" ("status", "last_seen_at");
