CREATE UNIQUE INDEX "uq_accounts_name" ON "accounts" ("name");
CREATE UNIQUE INDEX "uq_accounts_email" ON "accounts" ("email");
CREATE INDEX "idx_access_tokens_account_id" ON "access_tokens" ("account_id");
CREATE UNIQUE INDEX "uq_access_tokens_token_hash" ON "access_tokens" ("token_hash");
CREATE INDEX "idx_sessions_account_id" ON "sessions" ("account_id");
CREATE UNIQUE INDEX "uq_sessions_token_hash" ON "sessions" ("token_hash");
CREATE INDEX "idx_account_identities_account_id" ON "account_identities" ("account_id");
CREATE UNIQUE INDEX "uq_account_identities_strategy_subject" ON "account_identities" ("strategy", "subject");
CREATE UNIQUE INDEX "uq_account_identities_account_id_strategy" ON "account_identities" ("account_id", "strategy");
CREATE UNIQUE INDEX "uq_sign_in_attempts_state_hash" ON "sign_in_attempts" ("state_hash");
CREATE INDEX "idx_push_subscriptions_account" ON "push_subscriptions" ("account");
CREATE INDEX "idx_push_subscriptions_session" ON "push_subscriptions" ("session");
CREATE UNIQUE INDEX "uq_push_subscriptions_endpoint" ON "push_subscriptions" ("endpoint");
CREATE UNIQUE INDEX "uq_saved_queries_account_page" ON "saved_queries" ("account", "page");
CREATE INDEX "idx_products_kind" ON "products" ("kind");
CREATE INDEX "idx_products_article_id" ON "products" ("article_id");
CREATE UNIQUE INDEX "uq_stock_levels_product_id" ON "stock_levels" ("product_id");
CREATE INDEX "idx_articles_product_id" ON "articles" ("product_id");
CREATE INDEX "idx_articles_department" ON "articles" ("department");
CREATE INDEX "idx_inventory_movements_product_id_revision" ON "inventory_movements" ("product_id", "revision");
CREATE INDEX "idx_inventory_movements_article_id_revision" ON "inventory_movements" ("article_id", "revision");
CREATE INDEX "idx_inventory_movements_order_id" ON "inventory_movements" ("order_id");
CREATE INDEX "idx_reservations_order_id" ON "reservations" ("order_id");
CREATE INDEX "idx_reservations_article_id" ON "reservations" ("article_id");
