CREATE UNIQUE INDEX "uq_consumption_commands_order_id" ON "consumption_commands" ("order_id");
CREATE INDEX "idx_reviews_status" ON "reviews" ("status");
CREATE INDEX "idx_reviews_subject_id" ON "reviews" ("subject_id");
CREATE INDEX "idx_reviews_proposal_id" ON "reviews" ("proposal_id");
