CREATE INDEX "idx_orders_customer_id" ON "orders" ("customer_id");
CREATE INDEX "idx_orders_status" ON "orders" ("status");
CREATE INDEX "idx_orders_event_date" ON "orders" ("event_date");
CREATE INDEX "idx_bookings_product_id_from_date" ON "bookings" ("product_id", "from_date");
CREATE INDEX "idx_bookings_order_id" ON "bookings" ("order_id");
CREATE INDEX "idx_quotes_access_code" ON "quotes" ("access_code");
